-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 4
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 4 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 04', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 04 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-04.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga, em uma frase, o que controla o postgresql.conf.', 0.2, 'Controla **como o servidor funciona**: endereços, porta, conexões, memória, fuso horário e registros (log).', 'Nota cheia (0,2): ideia de funcionamento do servidor com dois exemplos. Metade (0,1): definição vaga. Zero (0): confunde com o pg_hba.conf.'),
      (v_atividade, 1, 2, 'Explique o que controla o pg_hba.conf e cite as informações que cada linha dele tem.', 0.4, 'Controla **quem pode conectar, de onde, a qual banco e como se autentica**. Cada linha tem: **tipo** (local/host), **banco**, **usuário**, **endereço** e **método** de autenticação.', 'Nota cheia (0,4): função + as cinco partes (aceitar quatro). Metade (0,2): só a função ou só as partes. Zero (0): confunde com parâmetros de memória/porta.'),
      (v_atividade, 1, 3, 'Escreva os comandos SQL que mostram onde estão os dois arquivos e explique quando eles são úteis.', 0.4, '**SHOW config_file;** e **SHOW hba_file;** (também SHOW data_directory;). São úteis para **achar o arquivo certo** que o servidor está usando antes de alterar, já que a localização muda conforme o sistema e a instalação.', 'Nota cheia (0,4): os dois comandos + utilidade. Metade (0,2): um comando com utilidade, ou os dois sem utilidade. Zero (0): comandos inexistentes.'),
      (v_atividade, 2, 1, 'Explique por que o back-end em outro servidor não consegue conectar.', 0.2, 'Com **''localhost''** o servidor só aceita conexões **da própria máquina**; o back-end em outro servidor não é atendido.', 'Nota cheia (0,2): explicação correta. Metade (0,1): "está bloqueado" sem dizer por quê. Zero (0): culpa a senha.'),
      (v_atividade, 2, 2, 'Diga qual valor colocar em listen_addresses e o que mais é preciso para o back-end entrar.', 0.4, '**listen_addresses = ''10.0.0.30''** (o IP do servidor de banco na rede interna; ''*'' só com firewall e pg_hba restritos). Também é preciso: **linha no pg_hba.conf** liberando o back-end, **porta liberada no firewall** para ele e **reiniciar** o serviço.', 'Nota cheia (0,4): valor coerente + pelo menos dois dos complementos (pg_hba, firewall, restart). Metade (0,2): só o valor ou só os complementos. Zero (0): "trust para todos".'),
      (v_atividade, 2, 3, 'Explique o parâmetro max_connections e o que considerar para os 150 acessos.', 0.4, '**max_connections** define o **máximo de conexões ao mesmo tempo**. Para 150 acessos, ajustar o valor com folga (ex.: 200) **ou** usar um **pool de conexões** no back-end, considerando que cada conexão usa memória do servidor.', 'Nota cheia (0,4): definição + decisão para os 150 (valor com folga ou pool) com justificativa. Metade (0,2): só a definição. Zero (0): definição errada.'),
      (v_atividade, 3, 1, 'Diga qual parâmetro corrige o horário e o valor para o Brasil.', 0.2, '**timezone = ''America/Sao_Paulo''**.', 'Nota cheia (0,2): parâmetro e valor. Metade (0,1): só o parâmetro. Zero (0): parâmetro errado.'),
      (v_atividade, 3, 2, 'Escreva o comando que altera esse parâmetro e o comando que aplica a mudança sem reiniciar.', 0.4, '**ALTER SYSTEM SET timezone = ''America/Sao_Paulo'';** e **SELECT pg_reload_conf();**', 'Nota cheia (0,4): os dois comandos. Metade (0,2): um. Zero (0): nenhum.'),
      (v_atividade, 3, 3, 'Explique qual parâmetro registra as conexões e o parâmetro shared_buffers, dizendo para que serve cada um.', 0.4, '**log_connections = on** registra **cada conexão** no log (quem, quando, de onde), ajudando a **auditoria**. **shared_buffers** é a **memória reservada para cache** de dados, que acelera as consultas.', 'Nota cheia (0,4): os dois explicados. Metade (0,2): um explicado. Zero (0): nenhum.'),
      (v_atividade, 4, 1, 'Explique o que essa linha permite.', 0.2, 'Permite que **qualquer usuário**, de **qualquer endereço** (0.0.0.0/0), entre em **qualquer banco** **sem senha** (trust).', 'Nota cheia (0,2): todos/qualquer endereço/sem senha. Metade (0,1): só "sem senha". Zero (0): interpretação errada.'),
      (v_atividade, 4, 2, 'Explique o risco dessa linha e por que o método trust não deve ser usado.', 0.4, 'Qualquer pessoa que alcance o servidor pela rede pode **entrar sem senha**, inclusive como superusuário, e **ler, alterar ou apagar** todos os dados. O **trust** dispensa autenticação, por isso nunca deve ser usado em servidor real.', 'Nota cheia (0,4): risco concreto + motivo do trust. Metade (0,2): "é inseguro" sem explicar. Zero (0): diz que é seguro.'),
      (v_atividade, 4, 3, 'Escreva uma linha segura que libere só o usuário app_escola no banco escola_db a partir do servidor 10.0.0.20, e diga o que fazer depois de salvar.', 0.4, '**host escola_db app_escola 10.0.0.20/32 scram-sha-256**; depois de salvar, **recarregar** a configuração (**SELECT pg_reload_conf();**) e **remover** a linha com trust.', 'Nota cheia (0,4): linha correta + reload. Metade (0,2): linha correta sem reload, ou com um campo errado e reload. Zero (0): mantém trust ou 0.0.0.0/0.'),
      (v_atividade, 5, 1, 'Escreva o comando que cria o banco escola_db em UTF8.', 0.2, '**CREATE DATABASE escola_db ENCODING ''UTF8'';**', 'Nota cheia (0,2): comando correto. Metade (0,1): sem a codificação. Zero (0): CREATE TABLE ou comando inexistente.'),
      (v_atividade, 5, 2, 'Escreva os comandos que criam o usuário app_escola com senha e permitem que ele se conecte ao banco.', 0.4, '**CREATE ROLE app_escola LOGIN PASSWORD ''senha-forte'';** e **GRANT CONNECT ON DATABASE escola_db TO app_escola;** (CREATE USER também é aceito).', 'Nota cheia (0,4): criação com login/senha + GRANT CONNECT. Metade (0,2): só um dos comandos. Zero (0): nenhum correto.'),
      (v_atividade, 5, 3, 'Explique por que não usar o usuário postgres na aplicação e como testar a conexão com o novo usuário.', 0.4, 'O postgres é **superusuário**: se a aplicação for invadida, o invasor ganha **poder total** sobre o servidor. A aplicação usa um usuário com **permissões mínimas**. Teste: **psql -U app_escola -h localhost -d escola_db**.', 'Nota cheia (0,4): motivo (poder total / permissões mínimas) + comando de teste. Metade (0,2): só um. Zero (0): defende usar o postgres.'),
      (v_atividade, 6, 1, 'Identifique na string o usuário, o servidor, a porta e o banco.', 0.2, 'Usuário **app_escola**; servidor **10.0.0.30**; porta **5432**; banco **escola_db**.', 'Nota cheia (0,2): os quatro. Metade (0,1): três. Zero (0): dois ou menos.'),
      (v_atividade, 6, 2, 'Explique o problema de a senha estar escrita no código.', 0.4, 'Quem tem acesso ao **código ou ao repositório** (colegas, GitHub, vazamento) passa a ter a **senha do banco**; trocar a senha exige **mudar o código**; o risco de **acesso indevido aos dados** aumenta.', 'Nota cheia (0,4): exposição + consequência. Metade (0,2): só "é inseguro". Zero (0): diz que não há problema.'),
      (v_atividade, 6, 3, 'Explique onde a string deve ficar e o cuidado com o arquivo .env no repositório.', 0.4, 'A string fica numa **variável de ambiente** (ex.: **DATABASE_URL**) configurada no servidor; o arquivo **.env**, se usado, fica **fora do repositório** (listado no .gitignore) e nunca é publicado.', 'Nota cheia (0,4): variável de ambiente + .env fora do Git. Metade (0,2): só um dos dois. Zero (0): sugere outro lugar público.'),
      (v_atividade, 7, 1, 'Descreva o caminho de uma requisição, do navegador até o banco.', 0.2, '**Navegador → (HTTPS) → back-end no 10.0.0.20 → (rede interna, porta 5432) → PostgreSQL no 10.0.0.30**; a resposta faz o caminho inverso.', 'Nota cheia (0,2): caminho com as três partes na ordem. Metade (0,1): falta uma parte. Zero (0): navegador direto ao banco.'),
      (v_atividade, 7, 2, 'Explique por que o banco deve ficar numa rede interna e não acessível pelo navegador.', 0.4, 'Na rede interna, **só o back-end (e os administradores)** alcançam o banco; ninguém da internet consegue tentar senhas ou explorar falhas do servidor de banco. O navegador nunca fala com o banco, só com o back-end, que aplica as regras.', 'Nota cheia (0,4): proteção + papel do back-end. Metade (0,2): só "mais seguro". Zero (0): defende acesso direto.'),
      (v_atividade, 7, 3, 'Explique a regra de firewall adequada para o servidor de banco.', 0.4, '**Liberar a porta 5432 apenas para o servidor do back-end (10.0.0.20)** e para a máquina de administração, bloqueando todo o resto.', 'Nota cheia (0,4): porta + origem restrita + bloqueio do resto. Metade (0,2): porta liberada sem restringir a origem. Zero (0): abrir para todos ou desligar o firewall.'),
      (v_atividade, 8, 1, 'Indique uma decisão para cada uma das três necessidades.', 0.2, '(1) ajustar **max_connections** e usar **pool de conexões**; (2) **backup automático em outro disco/servidor** e monitoramento; (3) **memória (shared_buffers) e disco rápido** (e índices).', 'Nota cheia (0,2): três decisões coerentes. Metade (0,1): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 8, 2, 'Explique o que é um pool de conexões e como ele ajuda na necessidade 1.', 0.4, 'O pool **mantém um conjunto de conexões abertas** e as **reaproveita** entre os pedidos, em vez de abrir uma nova a cada acesso. Na semana de matrícula evita estourar o **max_connections** e reduz o tempo de cada pedido.', 'Nota cheia (0,4): definição + benefício na situação. Metade (0,2): só a definição. Zero (0): definição errada.'),
      (v_atividade, 8, 3, 'Explique como deve ser o backup para atender a necessidade 2.', 0.4, 'Backup **automático e periódico** (ex.: diário), guardado **fora do servidor de banco** (outro disco, outro servidor ou nuvem), com **teste de restauração** de tempos em tempos.', 'Nota cheia (0,4): automático + em outro lugar + teste. Metade (0,2): dois dos três. Zero (0): backup no mesmo disco ou nenhum.'),
      (v_atividade, 9, 1, 'Diga qual mudança precisa de reload e qual precisa de restart.', 0.2, 'Nova linha no pg_hba.conf: **reload**. Troca de porta: **restart**.', 'Nota cheia (0,2): as duas corretas. Zero (0): trocadas.'),
      (v_atividade, 9, 2, 'Explique a diferença entre reload e restart quanto às conexões abertas.', 0.4, 'O **reload** aplica as mudanças **sem derrubar** as conexões abertas; o **restart** **para e inicia** o serviço, **derrubando** todas as conexões.', 'Nota cheia (0,4): diferença quanto às conexões. Metade (0,2): diferença vaga. Zero (0): invertida.'),
      (v_atividade, 9, 3, 'Explique quando fazer a troca da porta e o que mais precisa ser atualizado depois dela.', 0.4, 'Fazer a troca de porta **fora do horário de uso** (avisando a equipe), porque o restart derruba as conexões. Depois, atualizar a **porta na string de conexão** do back-end, no **firewall**, no **pgAdmin** e na **ficha de configuração**.', 'Nota cheia (0,4): quando + o que atualizar (ao menos dois). Metade (0,2): só um dos dois. Zero (0): fazer em pleno horário sem atualizar nada.'),
      (v_atividade, 10, 1, 'Liste os itens que a ficha de configuração deve ter.', 0.2, '**Parâmetros ajustados com valores**, **linhas do pg_hba.conf**, **banco e usuário da aplicação criados**, **string de conexão sem a senha real** e **desenho da infraestrutura** (versão e porta também).', 'Nota cheia (0,2): quatro ou mais itens. Metade (0,1): dois ou três. Zero (0): inclui a senha real como item.'),
      (v_atividade, 10, 2, 'Explique por que a ficha não deve conter a senha real e como a senha é informada à equipe.', 0.4, 'A ficha circula entre várias pessoas e pode ser arquivada ou publicada; com a senha nela, **qualquer leitor** acessaria o banco. A senha é passada pelo **cofre/gerenciador de senhas** da equipe, só para quem precisa.', 'Nota cheia (0,4): motivo + canal seguro. Metade (0,2): só um. Zero (0): manda incluir a senha.'),
      (v_atividade, 10, 3, 'Explique como conferir, depois de configurar, que o back-end consegue conectar com o usuário da aplicação e que um computador não autorizado não consegue.', 0.4, 'Do servidor do back-end, conectar com **psql -U app_escola -h 10.0.0.30 -d escola_db** (ou testar pela aplicação) e ver que entra; de um computador **não autorizado**, tentar a mesma conexão e confirmar a **recusa** (erro de pg_hba.conf ou bloqueio do firewall).', 'Nota cheia (0,4): teste positivo + teste negativo. Metade (0,2): só um dos testes. Zero (0): nenhum teste coerente.');
end $$;
